authors={'TAB':('Taberî','Câmiʿu’l-beyân','tabary'),'IK':('İbn Kesîr','Tefsîrü’l-Kur’âni’l-azîm','katheer'),'ZAM':('Zemahşerî','el-Keşşâf','zamakhshary'),'BAY':('Beyzâvî','Envârü’t-tenzîl','baidawy'),'DUR':('Süyûtî','ed-Dürrü’l-mensûr','seoty'),'BIQ':('Bikâî','Nazmü’d-dürer','beqaay')}
for prefix,(author,title,code) in authors.items():
 for a in range(1,8):
  sid=prefix+str(a)
  if sid not in scopes: continue
  site='https://quran.ksu.edu.sa/tafseer' if prefix in ['TAB','IK'] else 'https://quran-tafsir.net'
  url=f'{site}/{code}/sura1-aya{a}.html'
  registry[sid]=f'{author}, {title}, 1:{a}. [Sunulan asıl metin]({url}). {scopes[sid]} Dijital aktarım; matbu edisyon görüntüsüyle kollasyon yapılmadı.'
lex_files={'ABD':'abd_v','ALH':'alh','ALM':'alm_v','DLL':'dll_v','DYN':'dyn','GHDB':'ghdb_v','GHYR':'ghyr_v','HDY':'hdy','HMD':'hmd','MLK':'mlk_v','NAAM':'naam_v','QWM':'qwm','RBB':'rbb_v','RHM':'rhm','SMW':'smw','SRT':'srṭ','WSM':'wsm','YWM':'ywm_v'}
for name,f in lex_files.items():
 text=(W/'sources'/f'lex_{f}_maqayis.txt').read_text()
 url=re.search(r'https://arabiclexicon\.hawramani\.com/\?p=\d+#[a-z0-9]+',text).group()
 registry['M_'+name]=f'İbn Fâris, Mekâyîsü’l-luga, {name} kökü; Hawramani dictionary_7 birincil Arapça madde aktarımı. [Tam madde]({url}). Sunulan madde bütünü okundu; matbu edisyonla kollasyon yapılmadı. Köken açıklamaları müellifin kıyas/etimoloji görüşü olarak, modern tarihsel etimolojiden ayrılarak kullanıldı.'
names={'H_M395':'Müslim 395a','H_B4474':'Buhârî 4474','H_T2954':'Tirmizî 2954','H_B5999':'Buhârî 5999','H_B5988':'Buhârî 5988','H_M2747':'Müslim 2747a','H_T2859':'Tirmizî 2859','H_M223':'Müslim 223','H_AD1173':'Ebû Dâvûd 1173','H_B3':'Buhârî 3'}
for sid,h in matrix['hadith_checked'].items():
 registry[sid]=f'{names[sid]}, asıl Arapça matın/isnat ve numara, Sunnah.com koleksiyon aktarımı. [Asıl rivayet]({h["url"]}). Derece: {h["grade"]}; yetki: {h["grade_authority"]}. Denetlenen web satırları {h["web_lines"]}; ilişki sınıfı {h["relation"]}. Modern tercüme yerine Arapça matın esas alındı.'

used={s for d in annotations for s in d['source'].split('|')}
assert used<=registry.keys(),used-registry.keys()
prefix='<!-- enrichment/v1; TARGET 1; comprehensive; özgün r13; besmele 1:1; ek bloklar tek fiziksel satır -->\n\n'+'\n\n'.join(serialize(d) for d in at[0])+'\n\n'
pieces=[prefix]
for line_no,line in enumerate(BASE.read_text().splitlines(keepends=True),1):
 pieces.append(line)
 if line_no in at:
  pieces.append('\n'+'\n\n'.join(serialize(d) for d in at[line_no])+'\n')
pieces.append('\n## Kaynak kayıtları\n\n')
for sid in registry:
 if sid in used: pieces.append(f'- **{sid}** — {registry[sid]}\n\n')
OUT.write_text(''.join(pieces))
(W/'annotations.json').write_text(json.dumps(annotations,ensure_ascii=False,indent=2)+'\n')
(W/'novelty_coverage.json').write_text(json.dumps(dict(evidence_matrix_stage_before_composition=matrix['stage'],base_claim_paragraphs=73,novelty_blocks=[dict(id=a['id'],base_line=a['base_line'],scope=a.get('scope'),attestation=a['classical_attestation'],checked_sources=a['checked_sources']) for a in annotations if a['type']=='novelty'],no_universal_absence_claim=True,complete_classical_connection_audit=False,unresolved=matrix['corpus_limitations']),ensure_ascii=False,indent=2)+'\n')
print(json.dumps(dict(output=str(OUT),annotations=len(annotations),types=counts,sources=len(used),bytes=OUT.stat().st_size),ensure_ascii=False))
